def normal(value):
    s=str(value or '').replace('\u2011','-').replace('\u2013','-').replace('\u2014','-').replace('\u00a0',' ')
    return re.sub(r'sk-(?:proj-|svcacct-)?[A-Za-z0-9_-]{30,}','[credential omitted]',s)
def esc(value): return html.escape(normal(value))
def P(value,style='BodyZ'): return Paragraph(esc(value),styles[style])
